WITH flattened_attrs AS (SELECT id, service, log_ts, latency_ms, status_code, CAST((status_code & 8) != 0 AS INT) AS flag_bit8, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE TO_DATE(log_ts) < '2024-06-01') SELECT CASE WHEN retry_count >= 4 THEN 'PREMIUM' ELSE 'STANDARD' END AS retry_count_tier, CASE WHEN status_code >= 398 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, DATE_TRUNC('DAY', log_ts) AS activity_day, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, PERCENTILE_APPROX(retry_count, 0.5) AS retry_count_p50, PERCENT_RANK() OVER (PARTITION BY CASE WHEN retry_count >= 4 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY PERCENTILE_APPROX(retry_count, 0.5) DESC) AS retry_count_p50_percent_rank FROM flattened_attrs GROUP BY CASE WHEN retry_count >= 4 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN status_code >= 398 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('DAY', log_ts)
